import{_ as t,o,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/sheets/rows-columns-tabs-freeze.png",g=JSON.parse('{"title":"Work with rows, columns, and tabs","description":"Insert, delete, hide, freeze, move, and resize rows and columns, and add, rename, duplicate, reorder, or delete tabs.","frontmatter":{"title":"Work with rows, columns, and tabs","description":"Insert, delete, hide, freeze, move, and resize rows and columns, and add, rename, duplicate, reorder, or delete tabs.","type":"how-to"},"headers":[],"relativePath":"sheets/rows-columns-tabs.md","filePath":"sheets/rows-columns-tabs.md"}'),n={name:"sheets/rows-columns-tabs.md"};function l(i,e,c,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="work-with-rows-columns-and-tabs" tabindex="-1">Work with rows, columns, and tabs <a class="header-anchor" href="#work-with-rows-columns-and-tabs" aria-label="Permalink to &quot;Work with rows, columns, and tabs&quot;">​</a></h1><p>Insert, delete, hide, freeze, move, and resize rows and columns, and add, rename, duplicate, reorder, or delete tabs.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. With a viewer link the row and column menu items are unavailable.</li><li>On a phone, touch and hold a row number, column letter, cell, or tab instead of right-clicking.</li></ul></div><h2 id="insert-or-delete-rows-and-columns" tabindex="-1">Insert or delete rows and columns <a class="header-anchor" href="#insert-or-delete-rows-and-columns" aria-label="Permalink to &quot;Insert or delete rows and columns&quot;">​</a></h2><ol><li>Select a row by clicking its number, or a column by clicking its letter. To act on several, drag across the headers or <code>Shift</code>-click another header.</li><li>Right-click the selected header.</li><li>Select an item. The menu counts your selection: <ul><li>Rows: <strong>Insert row above</strong>, <strong>Insert row below</strong>, or <strong>Delete row</strong> (<strong>Insert 3 rows above</strong> when three are selected)</li><li>Columns: <strong>Insert column left</strong>, <strong>Insert column right</strong>, or <strong>Delete column</strong></li></ul></li></ol><p>You can also right-click any cell. The cell menu offers the same insert and delete items for the rows and columns the selection spans.</p><p>Formulas, merged cells, and formatting shift with the edit.</p><h2 id="hide-and-show-rows-or-columns" tabindex="-1">Hide and show rows or columns <a class="header-anchor" href="#hide-and-show-rows-or-columns" aria-label="Permalink to &quot;Hide and show rows or columns&quot;">​</a></h2><ol><li>Select the rows or columns and right-click a selected header.</li><li>Select <strong>Hide row</strong> or <strong>Hide column</strong> (<strong>Hide 3 rows</strong> when three are selected).</li></ol><p>A small arrow marks where rows or columns are hidden. To show them again, click the arrow, or right-click a header next to the hidden ones and select the <strong>Show</strong> item, such as <strong>Show rows 4–6</strong>.</p><h2 id="freeze-header-rows-or-columns" tabindex="-1">Freeze header rows or columns <a class="header-anchor" href="#freeze-header-rows-or-columns" aria-label="Permalink to &quot;Freeze header rows or columns&quot;">​</a></h2><ol><li>Right-click the number of the last row to keep in view. For a single header row, right-click row <strong>1</strong>.</li><li>Select <strong>Freeze up to row N</strong>, where <strong>N</strong> is that row.</li></ol><p>Rows 1 through <strong>N</strong> stay at the top while you scroll. To freeze columns, right-click the letter of the last column to keep in view and select <strong>Freeze up to column</strong> with that letter, such as <strong>Freeze up to column A</strong>.</p><p>To undo a freeze, right-click any row number and select <strong>Unfreeze rows</strong>, or right-click a column letter and select <strong>Unfreeze columns</strong>. You can freeze up to the first 1,000 rows or columns.</p><p><img src="'+s+'" alt="Row header menu with Insert, Delete, Hide, and Freeze up to row 1 items"></p><h2 id="move-rows-or-columns" tabindex="-1">Move rows or columns <a class="header-anchor" href="#move-rows-or-columns" aria-label="Permalink to &quot;Move rows or columns&quot;">​</a></h2><ol><li>Select the rows or columns by their headers.</li><li>Click and hold a selected header, then drag it to the new position.</li></ol><p>The rows or columns and their contents move together.</p><h2 id="resize-rows-and-columns" tabindex="-1">Resize rows and columns <a class="header-anchor" href="#resize-rows-and-columns" aria-label="Permalink to &quot;Resize rows and columns&quot;">​</a></h2><ul><li><strong>Resize:</strong> drag the line between two row numbers or two column letters.</li><li><strong>Fit to content:</strong> double-click that line. The column width or row height fits its contents.</li></ul><h2 id="add-a-tab" tabindex="-1">Add a tab <a class="header-anchor" href="#add-a-tab" aria-label="Permalink to &quot;Add a tab&quot;">​</a></h2><ul><li>To add a sheet, click <strong>+</strong> (<strong>Add sheet</strong>) at the right of the tab bar. It is named <strong>Sheet2</strong>, <strong>Sheet3</strong>, and so on.</li><li>To add a data source or lakehouse tab, click <strong>More tab types</strong> (the ▾ next to <strong>+</strong>) and select <strong>Connect data source (SQL)…</strong> or <strong>Connect lakehouse table…</strong>. See <a href="/docs/sheets/connect-a-database.html">Connect a database</a> and <a href="/docs/sheets/lakehouse.html">Lakehouse tables</a>.</li></ul><h2 id="rename-a-tab" tabindex="-1">Rename a tab <a class="header-anchor" href="#rename-a-tab" aria-label="Permalink to &quot;Rename a tab&quot;">​</a></h2><ol><li>Double-click the tab, or right-click it and select <strong>Rename</strong>.</li><li>Type the new name and press <code>Enter</code>. Press <code>Escape</code> to keep the old name.</li></ol><p>Tab names must be unique, ignoring case. A duplicate name shows <strong>Tab name &quot;…&quot; already exists.</strong> and stays in edit mode.</p><h2 id="duplicate-a-tab" tabindex="-1">Duplicate a tab <a class="header-anchor" href="#duplicate-a-tab" aria-label="Permalink to &quot;Duplicate a tab&quot;">​</a></h2><ol><li>Right-click a sheet tab.</li><li>Select <strong>Duplicate</strong>.</li></ol><p>The copy opens next to the original, named after it with <strong>(copy)</strong>, such as <strong>Sheet1 (copy)</strong>. Comments are not copied. A copy of a pivot table keeps its values but becomes a plain sheet.</p><h2 id="reorder-tabs" tabindex="-1">Reorder tabs <a class="header-anchor" href="#reorder-tabs" aria-label="Permalink to &quot;Reorder tabs&quot;">​</a></h2><p>Drag a tab left or right along the tab bar. Or right-click it and select <strong>Move left</strong> or <strong>Move right</strong>.</p><h2 id="delete-a-tab" tabindex="-1">Delete a tab <a class="header-anchor" href="#delete-a-tab" aria-label="Permalink to &quot;Delete a tab&quot;">​</a></h2><ol><li>Right-click the tab.</li><li>Select <strong>Delete</strong>.</li></ol><p>A document always keeps at least one tab, so <strong>Delete</strong> is missing when only one is left. If a pivot table reads from the tab, a <strong>Delete tab</strong> dialog lists the pivot tables that will go with it. Click <strong>Delete all</strong> to confirm.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Otherwise the tab is deleted without asking. To get it back, restore an earlier version from <a href="/docs/collaborate/version-history.html">version history</a>.</p></div><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>On a pivot table tab you can&#39;t insert or delete rows and columns, or merge cells.</li><li><strong>Duplicate</strong> works only for sheet tabs, not data source or lakehouse tabs.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/sort-and-filter.html">Sort and filter</a> to hide rows that don&#39;t match a condition.</li><li><a href="/docs/sheets/edit-and-format.html">Edit and format cells</a> to fill, move, and format data.</li><li><a href="/docs/sheets/formulas.html">Formulas</a> to reference cells on another tab.</li><li><a href="/docs/sheets/keyboard-shortcuts.html">Keyboard shortcuts</a>, including <code>Shift+Space</code> to select a row.</li></ul>',38)])])}const w=t(n,[["render",l]]);export{g as __pageData,w as default};
